import sys; sys.path.insert(0,'/workspace')
from unidecode import unidecode, UnidecodeError
bad_nonascii=[]; exc=[]; mapped=0
for cp in range(0x110000):
    if 0xd800 <= cp <= 0xdfff: continue
    c = chr(cp)
    try:
        r = unidecode(c)
    except Exception as e:
        exc.append((cp, type(e).__name__, str(e)[:60])); continue
    if r:
        mapped += 1
        try: r.encode('ascii')
        except UnicodeEncodeError: bad_nonascii.append((cp, r))
print('codepoints swept:', 0x110000 - 0x800)
print('mapped (non-empty result):', mapped)
print('unexpected exceptions:', len(exc), exc[:5])
print('results containing non-ASCII:', len(bad_nonascii), bad_nonascii[:10])
